WITH customers(customer_id, name) AS (
  VALUES (1, 'Ada'), (2, 'Ben'), (3, 'Chloe'), (NULL, 'Unknown')
), orders(order_id, customer_id, status) AS (
  VALUES (101, 1, 'DONE'), (102, 1, 'OPEN'), (103, 4, 'DONE'), (104, NULL, 'DONE')
)
SELECT c.customer_id, c.name, o.order_id, o.status
FROM customers c
LEFT JOIN orders o ON c.customer_id = o.customer_id
ORDER BY c.name, o.order_id;

WITH customers(customer_id, name) AS (
  VALUES (1, 'Ada'), (2, 'Ben'), (3, 'Chloe'), (NULL, 'Unknown')
), orders(order_id, customer_id, status) AS (
  VALUES (101, 1, 'DONE'), (102, 1, 'OPEN'), (103, 4, 'DONE'), (104, NULL, 'DONE')
)
SELECT c.customer_id, c.name, o.order_id, o.status
FROM customers c
LEFT JOIN orders o ON c.customer_id = o.customer_id AND o.status = 'DONE'
ORDER BY c.name, o.order_id;

WITH transactions(txn_id, day, amount) AS (
  VALUES (1, 1, 100), (2, 2, -30), (3, 2, 50), (4, 4, 20)
)
SELECT *, SUM(amount) OVER (
  ORDER BY day, txn_id
  ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
) AS running_total
FROM transactions
ORDER BY day, txn_id;

import pandas as pd
raw = ["12", "", "bad", "0"]
def parse_int(value):
    try:
        return int(value)
    except (TypeError, ValueError):
        return None
result = pd.DataFrame({"raw": raw, "parsed": [parse_int(v) for v in raw]})
result

import pandas as pd
rows = [{"id": 1, "version": 1}, {"id": 1, "version": 2}, {"id": 2, "version": 1}]
latest = {}
for row in rows:
    if row["id"] not in latest or row["version"] > latest[row["id"]]["version"]:
        latest[row["id"]] = row
assert latest[1]["version"] == 2
result = pd.DataFrame(latest.values())
result
